function isNonNegativeInt(value:unknown):boolean{ return Number.isInteger(value)&&(value as number)>=0; }
function normalizeValue(unit:string,value:number):number{
  if(unit==="V") return value*1000;
  if(unit==="uV") return Math.trunc(value/1000);
  return value;
}
export function classifySignal(millivolts:number):string{
  if(millivolts>=0&&millivolts<50) return "standby";
  if(millivolts>=50&&millivolts<200) return "idle";
  if(millivolts>=200&&millivolts<600) return "active";
  if(millivolts>=600&&millivolts<900) return "loaded";
  if(millivolts>=900) return "critical";
  return "negative";
}
function severityRank(label:string):number{
  if(label==="negative") return 5;
  if(label==="critical") return 4;
  if(label==="loaded") return 3;
  if(label==="active") return 2;
  if(label==="idle") return 1;
  return 0;
}
function collectAlerts(parsed:ParsedReading[]):string[]{
  const alerts:string[]=[];
  for(const reading of parsed){
    if(reading.millivolts>=900) alerts.push(reading.channel+":critical");
    else if(reading.millivolts<0) alerts.push(reading.channel+":negative");
    else if(reading.millivolts>=600&&reading.millivolts<900) alerts.push(reading.channel+":loaded");
  }
  return alerts;
}
function channelSummaries(parsed:ParsedReading[],labels:string[]):Record<string,ChannelSummary>{
  const channels:Record<string,ChannelSummary>={};
  for(let index=0;index<parsed.length;index++){
    const reading=parsed[index];
    const existing=channels[reading.channel];
    if(existing===undefined){ channels[reading.channel]={count:1,min:reading.millivolts,max:reading.millivolts,worst:labels[index]}; continue; }
    existing.count=existing.count+1;
    if(reading.millivolts<existing.min) existing.min=reading.millivolts;
    if(reading.millivolts>existing.max) existing.max=reading.millivolts;
    if(severityRank(labels[index])>severityRank(existing.worst)) existing.worst=labels[index];
  }
  return channels;
}
function buildReport(readingCount:number,channelCount:number,alertCount:number,labels:string[]):string{
  let worst="standby";
  for(const label of labels){ if(severityRank(label)>severityRank(worst)) worst=label; }
  return "readings="+readingCount+";channels="+channelCount+";alerts="+alertCount+";worst="+worst;
}
